"""Build v5 local-edit pairs: a real photo vs the same photo with one region regenerated by a VAE.

Why: a teammate's Qwen edit (only the memo's date rewritten, ~2% of pixels) passed every model.
Whole-image detectors average it away, and per-crop CNN scores spike on real texture too, so the
model needs pairs where *only* a pasted generated region differs (v4's aligned-pair idea, local).

Simulation of an edit tool (generate at ~1 MP, upscale, paste back):
  box (1-8% of the image) -> image scaled to <= 1 MP -> region through a VAE (latent optionally
  perturbed with noise to mimic re-generated content) -> upscaled to the box -> pasted with a
  feathered mask. The untouched real image is resized/saved exactly like the edited one.

Splits follow the source photo. Train/val: Qwen-Image VAE or SD1.4 VAE, saved as 320x320 crops
around the box at demo scale (short side 512), so a random 256 training crop sees the edit.
Test: Qwen, SD1.4 and Kandinsky MoVQ (never used in training), saved as whole images (short
side 1024) for demo-condition scoring, plus the box for crop-level analysis.
"""

import argparse
import hashlib
import math
import random
from pathlib import Path

import numpy as np
import pandas as pd
import torch
from PIL import Image, ImageFilter, ImageOps
from torchvision.transforms.functional import to_pil_image, to_tensor
from tqdm import tqdm

from src.models.model1_full_image.scripts.prepare_mixed_v3 import SOURCE_SHARE

EDITS_PER_IMAGE = {"team_real": 4, "fraudbench_real": 1, "coco": 1}
COCO_LIMIT = {"train": 1500, "val": 300, "test": 400}
TRAIN_VAES, TEST_VAES = ["qwen", "sd14"], ["qwen", "sd14", "movq"]


def load_vaes(names, device):
    from diffusers import AutoencoderKL, AutoencoderKLQwenImage, VQModel
    loaders = {"qwen": lambda: AutoencoderKLQwenImage.from_pretrained("Qwen/Qwen-Image", subfolder="vae"),
               "sd14": lambda: AutoencoderKL.from_pretrained("CompVis/stable-diffusion-v1-4", subfolder="vae"),
               "movq": lambda: VQModel.from_pretrained("kandinsky-community/kandinsky-2-2-decoder", subfolder="movq")}
    return {n: loaders[n]().to(device).eval() for n in names}


@torch.no_grad()
def regenerate(vae, name, region, noise, device):
    w, h = region.size
    padded = Image.new("RGB", (math.ceil(w / 16) * 16, math.ceil(h / 16) * 16))
    padded.paste(region)
    x = to_tensor(padded).unsqueeze(0).to(device) * 2 - 1
    if name == "qwen":
        z = vae.encode(x.unsqueeze(2)).latent_dist.mode()
        y = vae.decode(z + noise * z.std() * torch.randn_like(z)).sample[:, :, 0]
    elif name == "sd14":
        z = vae.encode(x).latent_dist.mean
        y = vae.decode(z + noise * z.std() * torch.randn_like(z)).sample
    else:
        z = vae.encode(x).latents
        y = vae.decode(z + noise * z.std() * torch.randn_like(z)).sample
    return to_pil_image((y[0].clamp(-1, 1).cpu() + 1) / 2).crop((0, 0, w, h))


def make_edit(image, vae, name, rng, device, area_range=(0.01, 0.08)):
    w, h = image.size
    area = rng.uniform(*area_range) * w * h
    aspect = math.exp(rng.uniform(math.log(0.5), math.log(2)))
    bw, bh = min(w, int(math.sqrt(area * aspect))), min(h, int(math.sqrt(area / aspect)))
    x0, y0 = rng.randint(0, w - bw), rng.randint(0, h - bh)
    box = (x0, y0, x0 + bw, y0 + bh)
    g = min(1.0, math.sqrt(1e6 / (w * h)))  # edit tools generate at about 1 MP
    small = image.resize((max(16, round(w * g)), max(16, round(h * g))), Image.Resampling.BICUBIC) if g < 1 else image
    sbox = tuple(round(v * g) for v in box)
    region = regenerate(vae, name, small.crop(sbox), rng.choice([0.0, 0.05, 0.1]), device)
    region = region.resize((bw, bh), Image.Resampling.BICUBIC)
    mask = Image.new("L", (bw, bh), 0)
    feather = max(2, min(bw, bh) // 12)
    mask.paste(255, (feather, feather, bw - feather, bh - feather))
    edited = image.copy()
    edited.paste(region, box[:2], mask.filter(ImageFilter.GaussianBlur(feather / 2)))
    return edited, box


def resize_short(image, short):
    s = short / min(image.size)
    return image.resize((round(image.width * s), round(image.height * s)), Image.Resampling.BICUBIC), s


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--metadata", required=True, help="mixed_v3/metadata.csv")
    parser.add_argument("--output", required=True)
    parser.add_argument("--seed", type=int, default=0)
    args = parser.parse_args()
    rng = random.Random(args.seed)
    torch.manual_seed(args.seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    meta = pd.read_csv(args.metadata, keep_default_na=False)
    reals = meta[meta.source.isin(EDITS_PER_IMAGE)]
    coco = reals[reals.source == "coco"]
    reals = pd.concat([reals[reals.source != "coco"]] + [coco[coco.split == s].sample(min(n, (coco.split == s).sum()), random_state=args.seed)
                                                        for s, n in COCO_LIMIT.items()])
    vaes = load_vaes(TEST_VAES, device)
    out = Path(args.output)
    rows = []
    for item in tqdm(list(reals.itertuples()), desc="local edits", mininterval=30):
        with Image.open(item.image_path) as image:
            image = ImageOps.exif_transpose(image).convert("RGB")
        names = TEST_VAES if item.split == "test" else TRAIN_VAES
        for k in range(EDITS_PER_IMAGE[item.source] if item.split != "test" else min(2, EDITS_PER_IMAGE[item.source])):
            name = names[rng.randrange(len(names))]
            edited, box = make_edit(image, vaes[name], name, rng, device)
            stem = f"{Path(item.image_path).stem}_{hashlib.md5(item.image_path.encode()).hexdigest()[:8]}_{k}"
            folder = out / item.split / item.source
            folder.mkdir(parents=True, exist_ok=True)
            if item.split == "test":
                pictures = {lbl: resize_short(p, 1024)[0] for lbl, p in [(0, image), (1, edited)]}
                scale = 1024 / min(image.size)
            else:  # 320 crop around the box at demo scale (short side 512)
                small = {lbl: resize_short(p, 512) for lbl, p in [(0, image), (1, edited)]}
                scale = small[0][1]
                cx, cy = (box[0] + box[2]) / 2 * scale, (box[1] + box[3]) / 2 * scale
                W, H = small[0][0].size
                left = int(min(max(0, cx - 160 + rng.randint(-40, 40)), W - 320))
                top = int(min(max(0, cy - 160 + rng.randint(-40, 40)), H - 320))
                pictures = {lbl: p.crop((left, top, left + 320, top + 320)) for lbl, (p, _) in small.items()}
            quality = rng.randint(85, 95)
            for label, picture in pictures.items():
                path = folder / f"{stem}_{'edit' if label else 'orig'}.jpg"
                picture.save(path, quality=quality)
                rows.append({"label": label, "split": item.split, "group_id": item.group_id,
                             "domain": f"local_edit:{name}" if label else f"local_orig:{item.source}",
                             "source": "local_edit" if label else "local_orig",
                             "generator_group": ("holdout" if name == "movq" else "seen") if label else "real",
                             "image_path": str(path.resolve()), "fake_type": "unknown" if label else "real",
                             "source_id": f"{item.source_id}:{k}", "edit_box": ",".join(str(round(v * scale)) for v in box) if label else "",
                             "edit_vae": name})
    pairs = pd.DataFrame(rows)
    base = pd.read_csv(args.metadata, keep_default_na=False)
    merged = pd.concat([base, pairs], ignore_index=True)
    # v3 shares sum to 1 per class; keep their ratios at 75% and give the pairs 25% of each class.
    shares = {**{k: v * 0.75 for k, v in SOURCE_SHARE.items()}, "local_orig": 0.25, "local_edit": 0.25}
    train = merged.split == "train"
    counts = merged[train].groupby("source").size()
    merged["sample_weight"] = [shares[s] / counts[s] if t else 0.0 for s, t in zip(merged.source, train)]
    merged.to_csv(out / "metadata.csv", index=False)
    print(pd.crosstab([pairs.split, pairs.domain], pairs.label))


if __name__ == "__main__":
    main()
